//! Actual cache crab descriptors and independently corrupted factory metadata.
use gielinor_cache::{game::{Definitions,GameCache},symbols};use gielinor_server::content::crab_carving;use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn seven_actual_items_and_seventy_nine_invalid_binding_cases(){let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let seq=symbols::load(&[Path::new(&dir)],"seq",None).unwrap();let stat=symbols::load(&[Path::new(&dir)],"stat",None).unwrap();let cache=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&cache),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let stats=cache.files(2,200,None).unwrap().unwrap();let ids=[("chisel",1755),("hundred_pirate_crab_shell_head",7538),("hundred_pirate_crab_shell_helm",7539),("crab_shell_broken",7541),("hundred_pirate_crab_shell_claw",7536),("hundred_pirate_crab_shell_gauntlet",7537),("crab_claw_broken",7540)];let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for(_,id)in ids{defs.items.insert(id as u32,gielinor_cache::definitions::ItemType::decode(&items[&(id as u32)]).unwrap());}defs.stats.insert(12,gielinor_cache::definitions::StatType::decode(&stats[&12]).unwrap());let r=crab_carving(&objects,&seq,&stat,&defs).unwrap();assert_eq!(r.len(),2);for(r,(raw,out,broken))in r.into_iter().zip([(7538,7539,7541),(7536,7537,7540)]){assert_eq!((r.exchange.tool,r.exchange.input,r.exchange.output,r.exchange.members,r.exchange.animation,r.level,r.xp_tenths,r.ticks),(1755,raw,out,true,Some(1280),15,325,3));let f=r.failure.unwrap();assert_eq!((f.output,f.xp_tenths,f.low,f.high),(broken,0,40,240));assert_eq!(f.message,"You accidentally break the crab material.");}
let mut refused=0;for(symbol,id)in ids{for mode in 0..10{let mut d=copy(&defs);let mut o=objects.clone();match mode{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Wrong".into(),2=>{let v=d.items.get_mut(&(id as u32)).unwrap();v.members=!v.members;},3=>d.items.get_mut(&(id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>{o.insert(symbol.into(),id+100000);},_=>{o.remove(symbol);}}assert!(crab_carving(&o,&seq,&stat,&d).is_err(),"{symbol} mode{mode}");refused+=1;}}
for mode in 0..9{let mut d=copy(&defs);let mut s=stat.clone();let mut q=seq.clone();match mode{0=>{s.remove("crafting");},1=>{s.insert("crafting".into(),13);},2=>{d.stats.remove(&12);},3=>d.stats.get_mut(&12).unwrap().name="Wrong".into(),4=>d.stats.get_mut(&12).unwrap().unreleased=true,5=>d.stats.get_mut(&12).unwrap().min_level=0,6=>d.stats.get_mut(&12).unwrap().max_level=98,7=>{q.remove("human_snailshellcutting");},8=>{q.insert("human_snailshellcutting".into(),1281);},_=>unreachable!()}assert!(crab_carving(&objects,&q,&s,&d).is_err());refused+=1;}assert_eq!(refused,79);println!("PG_CRAB_BINDINGS items=7 stat=12 sequence=1280 refused=79 zero_failure_xp=true");}
